/**
 * Guías "¿cómo se usa?" por módulo (Operación 2026-08; reescritas a fondo el
 * 28-ago-2026).
 *
 * Cada guía tiene: qué es el módulo (`resumen`), por qué existe y qué te pasa
 * si no lo usas (`porQue`, el contexto que un capturista nuevo no tiene), los
 * pasos reales de la pantalla y una captura del producto en
 * `/ayuda/<slug>.png`. El botón "?" del shell la abre; la primera visita a
 * cada módulo la abre sola una vez (localStorage).
 *
 * Reglas de esta pantalla, heredadas de la casa:
 *  - Cada paso corresponde a un control que EXISTE hoy; nada prometido.
 *  - Si un dato está pendiente de cotejo, un canal no está configurado o un
 *    módulo está en beta, el paso lo dice.
 *  - Los artículos y reglas citados se verificaron contra el corpus/código
 *    antes de escribirlos.
 * El campo `verificado` deja constancia de qué se leyó para redactar cada una.
 */
export interface GuiaModulo {
  slug: string
  titulo: string
  resumen: string
  /** Contexto: qué problema real resuelve y qué pasa si no lo haces. */
  porQue?: string
  pasos: string[]
  /** Ruta de la captura en /public/ayuda; opcional si aún no existe. */
  captura?: string
  /** Qué se leyó para redactar la guía (trazabilidad interna, no se muestra). */
  verificado?: string
}

